  "//--------------------------------------------------------------------------------------------------\n"
  "//\n"
  "//  Generic Unsigned Command Line Interface Option\n"
  "//\n"
  "//  This file is part of libpm library\n"
  "//\n"
  "//  Copyright (C) 2009, ..., 2024 Pierre Molinaro.\n"
  "//\n"
  "//  e-mail : pierre@pcmolinaro.name\n"
  "//\n"
  "//  This library is free software; you can redistribute it and/or modify it under the terms of the GNU Lesser General\n"
  "//  Public License as published by the Free Software Foundation; either version 2 of the License, or (at your option)\n"
  "//  any later version.\n"
  "//\n"
  "//  This program is distributed in the hope it will be useful, but WITHOUT ANY WARRANTY; without even the implied\n"
  "//  warranty of MERCHANDIBILITY or FITNESS FOR A PARTICULAR PURPOSE. See the GNU General Public License for\n"
  "//  more details.\n"
  "//\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "#include \"UIntCommandLineOption.h\"\n"
  "#include \"String-class.h\"\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "#include <string.h>\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "static UIntCommandLineOption * gFirstIntOption ;\n"
  "static UIntCommandLineOption * gLastIntOption ;\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "UIntCommandLineOption::UIntCommandLineOption (const char * inDomainName,\n"
  "                                              const char * inIdentifier,\n"
  "                                              const char inChar,\n"
  "                                              const char * inString,\n"
  "                                              const char * inComment,\n"
  "                                              const uint32_t inDefaultValue) :\n"
  "AbstractCommandLineOption (inDomainName, inIdentifier, inChar, inString, inComment),\n"
  "mNext (nullptr),\n"
  "mValue (inDefaultValue),\n"
  "mDefaultValue (inDefaultValue) {\n"
  "  if (nullptr == gFirstIntOption) {\n"
  "    gFirstIntOption = this ;\n"
  "  }else{\n"
  "    gLastIntOption->mNext = this ;\n"
  "  }\n"
  "  gLastIntOption = this ;\n"
  "}\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "void UIntCommandLineOption::\n"
  "setUIntOptionForCommandChar (const String & inCommandCommandLineOptionString,\n"
  "                             bool & outFound,\n"
  "                             bool & outCommandLineOptionStringIsValid) {\n"
  "  const int32_t optionLength = inCommandCommandLineOptionString.length () ;\n"
  "  outCommandLineOptionStringIsValid = (optionLength > 2) && (inCommandCommandLineOptionString.charAtIndex (1 COMMA_HERE) == '=') ;\n"
  "  uint32_t optionValue = 0 ;\n"
  "  for (int32_t i=2 ; (i<optionLength) && outCommandLineOptionStringIsValid ; i++) {\n"
  "    const uint32_t c = inCommandCommandLineOptionString.charAtIndex (i COMMA_HERE).u32 () ;\n"
  "    outCommandLineOptionStringIsValid = (c >= '0') && (c <= '9') ;\n"
  "    optionValue *= 10 ;\n"
  "    optionValue += c - '0' ;\n"
  "  }\n"
  "  outFound = false ;\n"
  "  UIntCommandLineOption * p = gFirstIntOption ;\n"
  "  if (outCommandLineOptionStringIsValid) {\n"
  "    while ((p != nullptr) && ! outFound) {\n"
  "      outFound = inCommandCommandLineOptionString.charAtIndex (0 COMMA_HERE).u32 () == uint32_t (p->mCommandChar) ;\n"
  "      if (outFound) {\n"
  "        p->mValue = optionValue ;\n"
  "      }\n"
  "      p = p->mNext ;\n"
  "    }\n"
  "  }\n"
  "}\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "void UIntCommandLineOption::\n"
  "setUIntOptionForCommandString (const String & inCommandCommandLineOptionString,\n"
  "                               bool & outFound,\n"
  "                               bool & outCommandLineOptionStringIsValid) {\n"
  "  const int32_t optionLength = inCommandCommandLineOptionString.length () ;\n"
  "  outCommandLineOptionStringIsValid = optionLength > 2 ;\n"
  "//--- Find '=' character\n"
  "  int32_t equalSignIndex = 0 ;\n"
  "  if (outCommandLineOptionStringIsValid) {\n"
  "    bool found = false ;\n"
  "    while ((equalSignIndex < optionLength) && outCommandLineOptionStringIsValid && !found) {\n"
  "      found = inCommandCommandLineOptionString.charAtIndex (equalSignIndex COMMA_HERE) == '=' ;\n"
  "      if (! found) {\n"
  "        equalSignIndex += 1 ;\n"
  "      }\n"
  "    }\n"
  "    outCommandLineOptionStringIsValid = found && (equalSignIndex > 0) && (equalSignIndex < (optionLength - 1)) ;\n"
  "  }\n"
  "//--- Compute option value\n"
  "  uint32_t optionValue = 0 ;\n"
  "  for (int32_t i=equalSignIndex+1 ; (i<optionLength) && outCommandLineOptionStringIsValid ; i++) {\n"
  "    const uint32_t c = inCommandCommandLineOptionString.charAtIndex (i COMMA_HERE).u32 () ;\n"
  "    outCommandLineOptionStringIsValid = (c >= '0') && (c <= '9') ;\n"
  "    optionValue *= 10 ;\n"
  "    optionValue += uint32_t (c - '0') ;\n"
  "  }\n"
  "//--- Search option\n"
  "  outFound = false ;\n"
  "  const String command = inCommandCommandLineOptionString.leftSubString (equalSignIndex) ;\n"
  "  if (outCommandLineOptionStringIsValid) {\n"
  "    UIntCommandLineOption * p = gFirstIntOption ;\n"
  "    while ((p != nullptr) && ! outFound) {\n"
  "      outFound = command == p->mCommandString ;\n"
  "      if (outFound) {\n"
  "        p->mValue = optionValue ;\n"
  "      }\n"
  "      p = p->mNext ;\n"
  "    }\n"
  "  }\n"
  "}\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "void UIntCommandLineOption::printUsageOfUIntOptions (void) {\n"
  "  UIntCommandLineOption * p = gFirstIntOption ;\n"
  "  while (p != nullptr) {\n"
  "    const char c = p->mCommandChar ;\n"
  "    if (c != '\\0') {\n"
  "      printf (\" [-%c=number]\", c) ;\n"
  "    }\n"
  "    if (p->mCommandString [0] != '\\0') {\n"
  "      printf (\" [--%s=number]\", p->mCommandString) ;\n"
  "    }\n"
  "    p = p->mNext ;\n"
  "  }\n"
  "}\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "void UIntCommandLineOption::printUIntOptions (void) {\n"
  "  UIntCommandLineOption * p = gFirstIntOption ;\n"
  "  while (p != nullptr) {\n"
  "    if (p->mCommandChar != '\\0') {\n"
  "      gCout.setConsoleForeColor (kBlueForeColor) ;\n"
  "      gCout.setConsoleTextAttribute (kBoldTextAttribute) ;\n"
  "      gCout.appendCString (\"-\") ;\n"
  "      gCout.appendASCIIChar (p->mCommandChar) ;\n"
  "      gCout.appendCString (\"=number\") ;\n"
  "      gCout.setConsoleTextAttribute (kAllAttributesOff) ;\n"
  "      gCout.appendNewLine () ;\n"
  "    }\n"
  "    if (p->mCommandString [0] != '\\0') {\n"
  "      gCout.setConsoleForeColor (kBlueForeColor) ;\n"
  "      gCout.setConsoleTextAttribute (kBoldTextAttribute) ;\n"
  "      gCout.appendCString (\"--\") ;\n"
  "      gCout.appendString (p->mCommandString) ;\n"
  "      gCout.appendCString (\"=number\") ;\n"
  "      gCout.setConsoleTextAttribute (kAllAttributesOff) ;\n"
  "      gCout.appendNewLine () ;\n"
  "    }\n"
  "    gCout.appendCString (\"    \") ;\n"
  "    gCout.appendString (p->mComment) ;\n"
  "    gCout.appendCString (\" (default value: \") ;\n"
  "    gCout.appendUnsigned (p->mDefaultValue) ;\n"
  "    gCout.appendCString (\")\\n\") ;\n"
  "    p = p->mNext ;\n"
  "  }\n"
  "}\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "void UIntCommandLineOption::getUIntOptionNameList (GenericUniqueArray <String> & outArray) {\n"
  "  UIntCommandLineOption * p = gFirstIntOption ;\n"
  "  while (p != nullptr) {\n"
  "    outArray.appendObject (p->mDomainName) ;\n"
  "    outArray.appendObject (p->mIdentifier) ;\n"
  "    p = p->mNext ;\n"
  "  }\n"
  "}\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "utf32 UIntCommandLineOption::getUIntOptionInvocationLetter (const String & inDomainName,\n"
  "                                                            const String & inIdentifier) {\n"
  "  utf32 result = utf32 (0) ;\n"
  "  UIntCommandLineOption * p = gFirstIntOption ;\n"
  "  bool found = false ;\n"
  "  while ((p != nullptr) && not found) {\n"
  "    found = (inDomainName == p->mDomainName) && (inIdentifier == p->mIdentifier) ;\n"
  "    result = utf32 ((uint32_t) p->mCommandChar) ;\n"
  "    p = p->mNext ;\n"
  "}\n"
  "  return result ;\n"
  "}\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "String UIntCommandLineOption::getUIntOptionInvocationString (const String & inDomainName,\n"
  "                                                             const String & inIdentifier) {\n"
  "  String result ;\n"
  "  UIntCommandLineOption * p = gFirstIntOption ;\n"
  "  bool found = false ;\n"
  "  while ((p != nullptr) && not found) {\n"
  "    found = (inDomainName == p->mDomainName) && (inIdentifier == p->mIdentifier) ;\n"
  "    result = p->mCommandString ;\n"
  "    p = p->mNext ;\n"
  "  }\n"
  "  return result ;\n"
  "}\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "String UIntCommandLineOption::getUIntOptionCommentString (const String & inDomainName,\n"
  "                                                          const String & inIdentifier) {\n"
  "  String result ;\n"
  "  UIntCommandLineOption * p = gFirstIntOption ;\n"
  "  bool found = false ;\n"
  "  while ((p != nullptr) && not found) {\n"
  "    found = (inDomainName == p->mDomainName) && (inIdentifier == p->mIdentifier) ;\n"
  "    result = p->mComment ;\n"
  "    p = p->mNext ;\n"
  "  }\n"
  "  return result ;\n"
  "}\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "uint32_t UIntCommandLineOption::getUIntOptionValue (const String & inDomainName,\n"
  "                                                    const String & inIdentifier) {\n"
  "  uint32_t result = 0 ;\n"
  "  UIntCommandLineOption * p = gFirstIntOption ;\n"
  "  bool found = false ;\n"
  "  while ((p != nullptr) && not found) {\n"
  "    found = (inDomainName == p->mDomainName) && (inIdentifier == p->mIdentifier) ;\n"
  "    result = p->mValue ;\n"
  "    p = p->mNext ;\n"
  "  }\n"
  "  return result ;\n"
  "}\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "void UIntCommandLineOption::setUIntOptionValue (const String & inDomainName,\n"
  "                                                const String & inIdentifier,\n"
  "                                                const uint32_t inValue) {\n"
  "  UIntCommandLineOption * p = gFirstIntOption ;\n"
  "  bool found = false ;\n"
  "  while ((p != nullptr) && not found) {\n"
  "    found = (inDomainName == p->mDomainName) && (inIdentifier == p->mIdentifier) ;\n"
  "    if (found) {\n"
  "      p->mValue = inValue ;\n"
  "    }\n"
  "    p = p->mNext ;\n"
  "  }\n"
  "}\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
   ;

