  "//  any later version.\n"
  "//\n"
  "//  This program is distributed in the hope it will be useful, but WITHOUT ANY WARRANTY; without even the implied\n"
  "//  warranty of MERCHANDIBILITY or FITNESS FOR A PARTICULAR PURPOSE. See the GNU General Public License for\n"
  "//  more details.\n"
  "//\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "#include \"F_GetPrime.h\"\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "//\n"
  "//           Get a prime integer greater than argument                                           \n"
  "//\n"
  "//--------------------------------------------------------------------------------------------------\n"
  "\n"
  "uint32_t getPrimeGreaterThan (const uint32_t inValue) {\n"
  "  const int32_t ARRAY_SIZE = 39 ;\n"
  "  const uint32_t array [ARRAY_SIZE] = {\n"
  "          3,\n"
  "        727,\n"
  "       1031, // > 2**10\n"
  "       1453,\n"
  "       2053, // > 2**11\n"
  "       2909,\n"
  "       4099, // > 2**12\n"
  "       5813,\n"
  "       8209, // > 2**13\n"
  "      11621,\n"
  "      16411, // > 2**14\n"
  "      23251,\n"
  "      32771, // > 2**15\n"
  "      46489,\n"
  "      64537, // > 2**16\n"
  "      92959,\n"
  "     131101, // > 2**17\n"
  "     185923,\n"
  "     262145, // > 2**18\n"
  "     371837,\n"
  "     524309, // > 2**19\n"
  "     743671,\n"
  "    1048583, // > 2**20\n"
  "    1487351,\n"
  "    2097169, // > 2**21\n"
  "    2974691,\n"
  "    4194319, // > 2**22\n"
  "    5949373,\n"
  "    8388617, // > 2**23\n"
  "   11898739,\n"
  "   16777259, // > 2**24\n"
  "   23797471,\n"
  "   33554467, // > 2**25\n"
  "   47594941,\n"
  "   67108879, // > 2**26\n"
  "   95189879,\n"
  "  134217757, // > 2**27\n"
  "  201326611,\n"
  "  402653189  // > 2**28\n"
  "  } ;\n"
  "  int32_t i = 0 ;\n"
  "  bool notFound = true ;\n"
  "  while (notFound && (i<ARRAY_SIZE)) {\n"
  "    notFound = inValue > array [i] ;\n"
  "    i += 1 ;\n"
  "  }\n"
  "  return array [i - 1] ;\n"
  "}\n"
  "\n"
  "//--------------------------------------------------------------------------------------------------\n"
   ;

