  "//------------------------------------------------------------------------------\n"
  "// From https://github.com/System-Glitch/SHA256\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "#include \"SHA256.h\"\n"
  "#include <cstring>\n"
  "#include <sstream>\n"
  "#include <iomanip>\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "constexpr std::array<uint32_t, 64> SHA256::K;\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "SHA256::SHA256(): m_blocklen(0), m_bitlen(0) {\n"
  "	m_state[0] = 0x6a09e667;\n"
  "	m_state[1] = 0xbb67ae85;\n"
  "	m_state[2] = 0x3c6ef372;\n"
  "	m_state[3] = 0xa54ff53a;\n"
  "	m_state[4] = 0x510e527f;\n"
  "	m_state[5] = 0x9b05688c;\n"
  "	m_state[6] = 0x1f83d9ab;\n"
  "	m_state[7] = 0x5be0cd19;\n"
  "}\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "void SHA256::update(const uint8_t * data, size_t length) {\n"
  "	for (size_t i = 0 ; i < length ; i++) {\n"
  "		m_data[m_blocklen++] = data[i];\n"
  "		if (m_blocklen == 64) {\n"
  "			transform();\n"
  "\n"
  "			// End of the block\n"
  "			m_bitlen += 512;\n"
  "			m_blocklen = 0;\n"
  "		}\n"
  "	}\n"
  "}\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "void SHA256::update(const std::string &data) {\n"
  "	update(reinterpret_cast<const uint8_t*> (data.c_str()), data.size());\n"
  "}\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "std::array<uint8_t,32> SHA256::digest() {\n"
  "	std::array<uint8_t,32> hash;\n"
  "\n"
  "	pad();\n"
  "	revert(hash);\n"
  "\n"
  "	return hash;\n"
  "}\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "uint32_t SHA256::rotr(uint32_t x, uint32_t n) {\n"
  "	return (x >> n) | (x << (32 - n));\n"
  "}\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "uint32_t SHA256::choose(uint32_t e, uint32_t f, uint32_t g) {\n"
  "	return (e & f) ^ (~e & g);\n"
  "}\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "uint32_t SHA256::majority(uint32_t a, uint32_t b, uint32_t c) {\n"
  "	return (a & (b | c)) | (b & c);\n"
  "}\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "uint32_t SHA256::sig0(uint32_t x) {\n"
  "	return SHA256::rotr(x, 7) ^ SHA256::rotr(x, 18) ^ (x >> 3);\n"
  "}\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "uint32_t SHA256::sig1(uint32_t x) {\n"
  "	return SHA256::rotr(x, 17) ^ SHA256::rotr(x, 19) ^ (x >> 10);\n"
  "}\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "void SHA256::transform() {\n"
  "	uint32_t maj, xorA, ch, xorE, sum, newA, newE, m[64];\n"
  "	uint32_t state[8];\n"
  "\n"
  "	for (uint8_t i = 0, j = 0; i < 16; i++, j += 4) { // Split data in 32 bit blocks for the 16 first words\n"
  "	//	m[i] = (m_data[j] << 24) | (m_data[j + 1] << 16) | (m_data[j + 2] << 8) | (m_data[j + 3]);\n"
  "		m[i]  = uint32_t (m_data[j + 0]) << 24 ;\n"
  "    m[i] |= uint32_t (m_data[j + 1]) << 16 ;\n"
  "    m[i] |= uint32_t (m_data[j + 2]) <<  8 ;\n"
  "    m[i] |= uint32_t (m_data[j + 3]) <<  0 ;\n"
  "	}\n"
  "\n"
  "	for (uint8_t k = 16 ; k < 64; k++) { // Remaining 48 blocks\n"
  "		m[k] = SHA256::sig1(m[k - 2]) + m[k - 7] + SHA256::sig0(m[k - 15]) + m[k - 16];\n"
  "	}\n"
  "\n"
  "	for(uint8_t i = 0 ; i < 8 ; i++) {\n"
  "		state[i] = m_state[i];\n"
  "	}\n"
  "\n"
  "	for (uint8_t i = 0; i < 64; i++) {\n"
  "		maj   = SHA256::majority(state[0], state[1], state[2]);\n"
  "		xorA  = SHA256::rotr(state[0], 2) ^ SHA256::rotr(state[0], 13) ^ SHA256::rotr(state[0], 22);\n"
  "\n"
  "		ch = choose(state[4], state[5], state[6]);\n"
  "\n"
  "		xorE  = SHA256::rotr(state[4], 6) ^ SHA256::rotr(state[4], 11) ^ SHA256::rotr(state[4], 25);\n"
  "\n"
  "		sum  = m[i] + K[i] + state[7] + ch + xorE;\n"
  "		newA = xorA + maj + sum;\n"
  "		newE = state[3] + sum;\n"
  "\n"
  "		state[7] = state[6];\n"
  "		state[6] = state[5];\n"
  "		state[5] = state[4];\n"
  "		state[4] = newE;\n"
  "		state[3] = state[2];\n"
  "		state[2] = state[1];\n"
  "		state[1] = state[0];\n"
  "		state[0] = newA;\n"
  "	}\n"
  "\n"
  "	for(uint8_t i = 0 ; i < 8 ; i++) {\n"
  "		m_state[i] += state[i];\n"
  "	}\n"
  "}\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "void SHA256::pad() {\n"
  "\n"
  "	uint64_t i = m_blocklen;\n"
  "	uint8_t end = m_blocklen < 56 \? 56 : 64;\n"
  "\n"
  "	m_data[i++] = 0x80; // Append a bit 1\n"
  "	while (i < end) {\n"
  "		m_data[i++] = 0x00; // Pad with zeros\n"
  "	}\n"
  "\n"
  "	if(m_blocklen >= 56) {\n"
  "		transform();\n"
  "		memset(m_data, 0, 56);\n"
  "	}\n"
  "\n"
  "	// Append to the padding the total message's length in bits and transform.\n"
  "	m_bitlen += m_blocklen * 8;\n"
  "	m_data[63] = uint8_t (m_bitlen >>  0) ;\n"
  "	m_data[62] = uint8_t (m_bitlen >>  8) ;\n"
  "	m_data[61] = uint8_t (m_bitlen >> 16) ;\n"
  "	m_data[60] = uint8_t (m_bitlen >> 24) ;\n"
  "	m_data[59] = uint8_t (m_bitlen >> 32) ;\n"
  "	m_data[58] = uint8_t (m_bitlen >> 40) ;\n"
  "	m_data[57] = uint8_t (m_bitlen >> 48) ;\n"
  "	m_data[56] = uint8_t (m_bitlen >> 56) ;\n"
  "	transform () ;\n"
  "}\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "void SHA256::revert(std::array<uint8_t, 32> & hash) {\n"
  "	// SHA uses big endian byte ordering\n"
  "	// Revert all bytes\n"
  "	for (uint8_t i = 0 ; i < 4 ; i++) {\n"
  "		for(uint8_t j = 0 ; j < 8 ; j++) {\n"
  "			hash[i + (j * 4)] = (m_state[j] >> (24 - i * 8)) & 0x000000ff;\n"
  "		}\n"
  "	}\n"
  "}\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
  "\n"
  "std::string SHA256::toString(const std::array<uint8_t, 32> & digest) {\n"
  "	std::stringstream s;\n"
  "	s << std::setfill('0') << std::hex;\n"
  "\n"
  "	for(uint8_t i = 0 ; i < 32 ; i++) {\n"
  "		s << std::setw(2) << (unsigned int) digest[i];\n"
  "	}\n"
  "\n"
  "	return s.str();\n"
  "}\n"
  "\n"
  "//------------------------------------------------------------------------------\n"
   ;

